import {CHARACTERS, characterOf} from '@binary/shared';
import {useEffect, useState} from 'react';
import {View} from 'react-native';
import {SvgXml} from 'react-native-svg';

import {CHARACTER_SVGS, type Mood} from '@/lib/character-faces';

export type {Mood};

interface CharacterProps {
  /** The agent's avatar; older or empty values get a default character. */
  avatar: string | null;
  mood?: Mood;
  size?: number;
}

/**
 * A whole character, drawn from the same SVG as the web app (generated by
 * apps/web/scripts/export-character-faces.tsx).
 */
export function Character({avatar, size = 160}: Omit<CharacterProps, 'mood'>) {
  return (
    <SvgXml
      xml={CHARACTER_SVGS[characterOf(avatar)].full}
      width={size}
      height={size}
    />
  );
}

/** While talking, the mouth opens and closes; other moods hold still. */
function useMouth(mood: Mood): Mood {
  const [isOpen, setIsOpen] = useState(true);
  useEffect(() => {
    if (mood !== 'talking') {
      return;
    }
    const timer = setInterval(() => setIsOpen((open) => !open), 180);
    return () => clearInterval(timer);
  }, [mood]);
  return mood === 'talking' && !isOpen ? 'idle' : mood;
}

/** The character's face in a round tile tinted with its color. */
export function CharacterAvatar({
  avatar,
  mood = 'idle',
  size = 40,
}: CharacterProps) {
  const id = characterOf(avatar);
  const shown = useMouth(mood);
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={{
        width: size,
        height: size,
        borderRadius: size / 2,
        overflow: 'hidden',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: `${CHARACTERS[id].color}2e`,
      }}
    >
      <SvgXml
        xml={CHARACTER_SVGS[id].face[shown]}
        width={size * 1.05}
        height={size * 1.05}
      />
    </View>
  );
}
